<?php require 'config.php';$q=trim($_GET['q']??'');$s=db()->prepare('SELECT * FROM locations WHERE ?="" OR city LIKE ? OR country LIKE ? OR zip LIKE ? OR name LIKE ?');$l="%$q%";$s->execute([$q,$l,$l,$l,$l]);head('Locations');?>
<div class="wrap"><h1>Find a location near you</h1><form class="box"><div class="row"><input name="q" value="<?=e($q)?>" placeholder="Enter city, ZIP code or country"><button class="btn">Search</button></div></form><br><div class="grid"><?php foreach($s as $x)echo "<div class='card'><h3>📍 ".e($x['name'])."</h3><p>".e($x['address'])."<br>".e($x['city']).", ".e($x['country'])." ".e($x['zip'])."<br>🕒 ".e($x['hours'])."</p></div>";?></div></div><?php foot();
